with deduped as (select * from (select *, row_number() over (partition by store_id, product_id order by last_restock desc, id) as dedup_rank from inventory) ranked where dedup_rank = 1) select case when quantity >= 251 then 'HIGH' else 'LOW' end as quantity_tier, date_trunc('month', last_restock) as activity_month, product_id, count(distinct id) as distinct_ids, round(avg(quantity), 2) as avg_quantity, round(avg(quantity), 2) as avg_quantity_2, max(quantity) as max_quantity, bit_or(quantity) as quantity_bit_or from deduped group by quantity_tier, activity_month, product_id having distinct_ids > 1 order by distinct_ids nulls first;
